package com.interview.mysqlescdc.verifier.rebuild;
import java.util.UUID;
public record RebuildRequest(UUID runId,String reason,String topic,int pageSize){public static final String TOPIC="product-search-revisions";public static final int PAGE_SIZE=200;public RebuildRequest{if(runId==null||reason==null||reason.isBlank()||!TOPIC.equals(topic)||pageSize<1||pageSize>1000)throw new IllegalArgumentException("run, supported reason, configured topic and pageSize 1..1000 required");if(!java.util.Set.of("NORMAL","MYSQL_BINLOG_GAP").contains(reason))throw new IllegalArgumentException("unsupported rebuild reason");}}
